/* ---------- odvozené hodnoty ---------- */
function zemeKratce(z){ return (z||"neurčeno").split(" (")[0]; }
function rokOd(r){ const m=(r||"").match(/(1[6-9]\d\d|20\d\d)/); return m? +m[1] : null; }
function nominalCislo(n){
  if(!n) return null; const s=n.replace(",", ".");
  const m=s.match(/(\d+(?:\.\d+)?)?\s*(½|¼)?/); if(!m || (!m[1] && !m[2])) return null;
  let v=m[1]? parseFloat(m[1]) : 0; if(m[2]==="½") v+=.5; if(m[2]==="¼") v+=.25;
  if(/million/i.test(n)) v*=1e6; else if(/tausend/i.test(n)) v*=1e3;
  return v;
}
