/* ---------- stav filtrů ---------- */
const F = {q:"",zeme:"",rokOd:"",rokDo:"",mena:"",nom:"",stav:"",zach:"",cena:"",cenaOd:"",cenaDo:"",jist:"",jistC:"",davka:"",skup:false,sort:"poradi",dir:1,size:"m"};
